import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { cellCenter, mapExtent, pointToCell, steps } from "./grid";
import type { Cell, Grid, Point } from "./types";

// Generated by `go test ./internal/scene -run Vectors -update`.
const vectors: {
  grids: Record<string, Grid>;
  extents: Record<string, Point>;
  vectors: { grid: string; cell: Cell; center: Point; probe: Point; probeCell: Cell }[];
  steps: { grid: string; a: Cell; b: Cell; steps: number }[];
} = JSON.parse(
  readFileSync(fileURLToPath(new URL("../../../internal/scene/testdata/grid_vectors.json", import.meta.url)), "utf8"),
);

describe("grid math matches Go", () => {
  for (const v of vectors.vectors) {
    it(`${v.grid} ${v.cell.col},${v.cell.row}`, () => {
      const g = vectors.grids[v.grid];
      const c = cellCenter(g, v.cell);
      expect(c.x).toBeCloseTo(v.center.x, 9);
      expect(c.y).toBeCloseTo(v.center.y, 9);
      expect(pointToCell(g, v.probe)).toEqual(v.probeCell);
      expect(pointToCell(g, v.center)).toEqual(v.cell);
    });
  }
  for (const [name, ext] of Object.entries(vectors.extents)) {
    it(`extent ${name}`, () => {
      const e = mapExtent(vectors.grids[name], 7, 5);
      expect(e.x).toBeCloseTo(ext.x, 9);
      expect(e.y).toBeCloseTo(ext.y, 9);
    });
  }
  for (const v of vectors.steps) {
    it(`${v.grid} steps ${v.a.col},${v.a.row} -> ${v.b.col},${v.b.row}`, () => {
      expect(steps(vectors.grids[v.grid], v.a, v.b)).toBe(v.steps);
    });
  }
});
